#!/usr/bin/env bash
# Inject a system-appearance-aware macOS app icon into a Tauri-built .app.
#
# Tauri's bundler copies src-tauri/icons/icon.icns as a single CFBundleIconFile.
# That cannot carry a light/dark pair, and the icns crate it historically used
# encodes the small slots (icp4/icp5/ic11) as JPEG 2000 — which macOS 26/27
# Finder renders as coloured noise in list/sidebar rows. This script compiles
# src-tauri/AppIcon.icon (generated by the cinder repo's
# scripts/generate-icons.mjs --agent-repo) into Assets.car and points
# CFBundleIconName at it; icon.icns — the all-PNG rebuild — stays as the
# classic fallback for macOS < 26.
#
# Usage:
#   scripts/apply-macos-app-icon.sh --compile-only
#   scripts/apply-macos-app-icon.sh [path/to/Warden.app]
#
# --compile-only writes src-tauri/Assets.car for tauri.macos.conf.json, so the
# asset is bundled and signed in the normal Tauri pipeline. Manual mode injects
# an existing .app and must still run BEFORE codesigning.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ICON_SRC="$ROOT/src-tauri/AppIcon.icon"
MODE="${1:-}"
APP=""

if [ "$MODE" = "--compile-only" ]; then
  OUT="${2:-$ROOT/src-tauri/Assets.car}"
elif [ "$MODE" = "--help" ] || [ "$MODE" = "-h" ]; then
  echo "usage: apply-macos-app-icon.sh [--compile-only [output.car] | [path/to/Warden.app]]"
  exit 0
else
  OUT=""
  APP="$MODE"
  if [ -z "$APP" ]; then
    APP="$(ls -d "$ROOT"/src-tauri/target/release/bundle/macos/*.app 2>/dev/null | head -1 || true)"
  fi
fi
if [ "$MODE" != "--compile-only" ] && { [ -z "$APP" ] || [ ! -d "$APP" ]; }; then
  echo "ERROR: no .app bundle found; pass its path explicitly" >&2
  exit 1
fi
if [ "$(uname -s)" != "Darwin" ]; then
  echo "ERROR: Icon Composer icons can only be compiled on macOS" >&2
  exit 1
fi
if [ ! -f "$ICON_SRC/icon.json" ] || [ ! -f "$ICON_SRC/Assets/glyph.svg" ]; then
  echo "ERROR: $ICON_SRC is incomplete; run 'node scripts/generate-icons.mjs --agent-repo ../warden' in the cinder repo" >&2
  exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/warden-appicon.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
mkdir -p "$TMP/compiled"

# actool occasionally races its CoreSVG appearance specialisation on a first
# compile — the car comes out without the dark-aqua IconGroup and the tile
# would never switch. Verify by parsing the assetutil JSON (the string also
# sits in the car binary, so grep alone is fine, but the JSON check is
# precise about WHERE the appearance lives) and retry the compile once.
verify_dark_rendition() {
  xcrun --sdk macosx assetutil --info "$1" 2>/dev/null | python3 -c "
import json, sys
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(1)
ok = any(
    isinstance(e, dict)
    and e.get('AssetType') in ('IconGroup', 'IconImageStack')
    and e.get('Appearance') == 'NSAppearanceNameDarkAqua'
    for e in data
)
sys.exit(0 if ok else 1)
"
}

compile_icon() {
  rm -rf "$TMP/compiled"
  mkdir -p "$TMP/compiled"
  xcrun actool "$ICON_SRC" \
    --compile "$TMP/compiled" \
    --output-format human-readable-text \
    --notices --warnings --errors \
    --output-partial-info-plist "$TMP/info.plist" \
    --app-icon AppIcon \
    --include-all-app-icons \
    --enable-on-demand-resources NO \
    --development-region en \
    --target-device mac \
    --minimum-deployment-target 26.0 \
    --platform macosx
}

compile_icon
if ! verify_dark_rendition "$TMP/compiled/Assets.car"; then
  echo "first compile lacked the dark-aqua rendition — retrying once" >&2
  compile_icon
fi

if [ ! -f "$TMP/compiled/Assets.car" ]; then
  echo "ERROR: actool produced no Assets.car" >&2
  exit 1
fi
if ! verify_dark_rendition "$TMP/compiled/Assets.car"; then
  echo "ERROR: Assets.car has no dark-aqua IconGroup after retry — the dark tile would not switch" >&2
  exit 1
fi

if [ "$MODE" = "--compile-only" ]; then
  mkdir -p "$(dirname "$OUT")"
  cp "$TMP/compiled/Assets.car" "$OUT"
  echo "Compiled appearance-aware app icon to $OUT"
  exit 0
fi

RES="$APP/Contents/Resources"
INFO="$APP/Contents/Info.plist"
if [ ! -d "$RES" ] || [ ! -f "$INFO" ]; then
  echo "ERROR: $APP is not a valid .app bundle" >&2
  exit 1
fi

cp "$TMP/compiled/Assets.car" "$RES/Assets.car"
if ! /usr/libexec/PlistBuddy -c "Print :CFBundleIconName" "$INFO" >/dev/null 2>&1; then
  /usr/libexec/PlistBuddy -c "Add :CFBundleIconName string AppIcon" "$INFO"
else
  /usr/libexec/PlistBuddy -c "Set :CFBundleIconName AppIcon" "$INFO"
fi

echo "Injected appearance-aware app icon into $APP (Assets.car + CFBundleIconName=AppIcon)"
